+    const stone = mat(0x293b45), trim = mat(gate.open ? 0xffd277 : 0x9f9070, 0.35, { emissive: gate.open ? 0x9b5b13 : 0x17130d, emissiveIntensity: 0.45 });
+    addMesh(group, shared.box, stone, v3(-0.9, 1.15, 0), { scale: [0.28, 2.3, 0.38] });
+    addMesh(group, shared.box, stone, v3(0.9, 1.15, 0), { scale: [0.28, 2.3, 0.38] });
