604:   const joystick = document.getElementById('joystick');
605:   const stickKnob = document.getElementById('stickKnob');
606:   if (joystick && stickKnob) {
607:     const moveStick = (event) => {
608:       const rect = joystick.getBoundingClientRect();
609:       const max = Math.max(1, rect.width * 0.5 - stickKnob.offsetWidth * 0.5 - 4);
610:       let dx = event.clientX - (rect.left + rect.width * 0.5);
611:       let dy = event.clientY - (rect.top + rect.height * 0.5);
612:       const distance = Math.hypot(dx, dy);
613:       if (distance > max) { dx *= max / distance; dy *= max / distance; }
614:       let x = dx / max, y = dy / max;
615:       const magnitude = Math.hypot(x, y);
616:       if (magnitude < 0.12) x = y = 0;
617:       else if (magnitude > 1) { x /= magnitude; y /= magnitude; }
618:       input.stickX = x;
619:       input.stickY = y;
620:       stickKnob.style.transform = `translate(${dx}px, ${dy}px)`;
621:     };
622:     joystick.addEventListener('pointerdown', (event) => {
623:       event.preventDefault();
624:       joystick.setPointerCapture(event.pointerId);
625:       joystick.classList.add('active');
626:       moveStick(event);
627:     });
628:     joystick.addEventListener('pointermove', (event) => {
629:       if (joystick.hasPointerCapture(event.pointerId)) moveStick(event);
630:     });
631:     const releaseStick = (event) => {
632:       if (event.cancelable) event.preventDefault();
633:       input.stickX = 0;
634:       input.stickY = 0;
635:       joystick.classList.remove('active');
636:       stickKnob.style.transform = 'translate(0px, 0px)';
637:     };
638:     joystick.addEventListener('pointerup', releaseStick);
639:     joystick.addEventListener('pointercancel', releaseStick);
