685:   if (joystick && stickKnob) {
686:     const moveStick = (event) => {
687:       const rect = joystick.getBoundingClientRect();
688:       const max = Math.max(1, rect.width * 0.5 - stickKnob.offsetWidth * 0.5 - 4);
689:       let dx = event.clientX - (rect.left + rect.width * 0.5);
690:       let dy = event.clientY - (rect.top + rect.height * 0.5);
691:       const distance = Math.hypot(dx, dy);
692:       if (distance > max) { dx *= max / distance; dy *= max / distance; }
693:       let x = dx / max, y = dy / max;
694:       const magnitude = Math.hypot(x, y);
695:       if (magnitude < 0.12) x = y = 0;
696:       else if (magnitude > 1) { x /= magnitude; y /= magnitude; }
