23:       const size = bounds.getSize(new THREE.Vector3());
24:       if (!Number.isFinite(size.y) || size.y <= 0) throw new Error(`Model has no usable height: ${url}`);
25:       const center = bounds.getCenter(new THREE.Vector3());
26:       const normalized = new THREE.Group();
27:       normalized.name = id;
28:       source.scale.multiplyScalar(height / size.y);
29:       source.position.set(-center.x * height / size.y, -bounds.min.y * height / size.y, -center.z * height / size.y);
