40:       this.onStatus({ state: 'loaded', id, url, loaded: 1, total: 1 });
41:       return normalized;
42:     }).catch((error) => {
43:       this.cache.delete(id);
44:       this.onStatus({ state: 'error', id, url, error });
45:       throw error;
46:     });
47:     this.cache.set(id, task);
