const perfSamples = [];
if (new URLSearchParams(location.search).has('perf')) {
  window.__gamePerf = {
    samples: perfSamples,
    treeInstances: () => environmentAssets.instances.size,
    treeMeshes: () => {
      let count = 0;
      for (const root of environmentAssets.instances) root.traverse((object) => { if (object.isMesh) count++; });
      return count;
    },
    snapshot: () => ({
      fps: perfSamples.length > 1 ? 1000 / (perfSamples.reduce((sum, sample) => sum + sample.dt, 0) / (perfSamples.length - 1)) : 0,
      calls: renderer.info.render.calls,
      triangles: renderer.info.render.triangles,
      geometries: renderer.info.memory.geometries,
      textures: renderer.info.memory.textures,
      treeInstances: environmentAssets.instances.size,
      treeMeshes: window.__gamePerf.treeMeshes(),
      position: hero ? [Math.round(hero.x), Math.round(hero.y)] : null,
    }),
    moveTo: (x, y) => { hero.x = x; hero.y = y; hero.vx = hero.vy = 0; },
  };
}
function render(now) {
  const dt = Math.min(0.033, Math.max(0, (now - last) / 1000));
  last = now;
  update(dt);
  renderer.render(scene, camera);
  if (window.__gamePerf) {
    perfSamples.push({ time: now, dt, calls: renderer.info.render.calls, triangles: renderer.info.render.triangles });
    if (perfSamples.length > 120) perfSamples.shift();
  }
  requestAnimationFrame(render);
}
reset();

