14:   async load(url, { id = url, height = 3.8 } = {}) {
15:     if (this.cache.has(id)) return this.cache.get(id);
16:     this.onStatus({ state: 'loading', id, url, loaded: 0, total: 0 });
17:     const task = this.loader.loadAsync(url, (event) => {
18:       this.onStatus({ state: 'loading', id, url, loaded: event.loaded, total: event.total || 0 });
19:     }).then((gltf) => {
20:       const source = gltf.scene;
21:       source.updateMatrixWorld(true);
22:       const bounds = new THREE.Box3().setFromObject(source);
23:       const size = bounds.getSize(new THREE.Vector3());
24:       if (!Number.isFinite(size.y) || size.y <= 0) throw new Error(`Model has no usable height: ${url}`);
25:       const center = bounds.getCenter(new THREE.Vector3());
26:       const normalized = new THREE.Group();
27:       normalized.name = id;
28:       source.scale.multiplyScalar(height / size.y);
29:       source.position.set(-center.x * height / size.y, -bounds.min.y * height / size.y, -center.z * height / size.y);
30:       source.traverse((object) => {
31:         if (!object.isMesh) return;
32:         object.castShadow = true;
33:         object.receiveShadow = true;
34:         object.frustumCulled = true;
35:         object.userData.assetId = id;
36:       });
37:       normalized.add(source);
38:       normalized.userData.assetId = id;
39:       normalized.userData.sourceUrl = url;
40:       this.onStatus({ state: 'loaded', id, url, loaded: 1, total: 1 });
41:       return normalized;
42:     }).catch((error) => {
43:       this.cache.delete(id);
44:       this.onStatus({ state: 'error', id, url, error });
45:       throw error;
46:     });
47:     this.cache.set(id, task);
48:     return task;
49:   }
